import { useState, useRef, useEffect } from "react";

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL || "http://localhost:3001";
const STATUS = { IDLE: "idle", PREVIEWING: "previewing", PROCESSING: "processing", DONE: "done", ERROR: "error" };

export default function App() {
  const [file, setFile]         = useState(null);
  const [status, setStatus]     = useState(STATUS.IDLE);
  const [preview, setPreview]   = useState(null);
  const [results, setResults]   = useState(null);
  const [errorMsg, setErrorMsg] = useState("");
  const [dragOver, setDragOver] = useState(false);
  const [progress, setProgress] = useState(0);
  const [page, setPage]         = useState("dashboard");
  const [history, setHistory]   = useState([]);
  const inputRef = useRef();

  useEffect(() => {
    if (status === STATUS.PROCESSING) {
      setProgress(0);
      const t = setInterval(() => setProgress(p => Math.min(p + 2, 90)), 150);
      return () => clearInterval(t);
    }
    if (status === STATUS.DONE) setProgress(100);
  }, [status]);

  function handleFile(f) {
    if (!f) return;
    if (!f.name.endsWith(".zip")) { setErrorMsg("Please upload a .zip file from Migration Manager."); return; }
    setFile(f); setStatus(STATUS.IDLE); setPreview(null); setResults(null); setErrorMsg("");
  }
  function handleDrop(e) { e.preventDefault(); setDragOver(false); handleFile(e.dataTransfer.files[0]); }

  async function handlePreview() {
    if (!file) return;
    setStatus(STATUS.PREVIEWING); setErrorMsg("");
    try {
      const fd = new FormData(); fd.append("migrationZip", file);
      const res = await fetch(`${BACKEND_URL}/api/preview-migration`, { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok || !data.success) throw new Error(data.error || "Preview failed");
      setPreview(data); setStatus(STATUS.IDLE);
    } catch (err) { setErrorMsg(err.message); setStatus(STATUS.ERROR); }
  }

  async function handleProcess() {
    if (!file) return;
    setStatus(STATUS.PROCESSING); setErrorMsg("");
    try {
      const fd = new FormData(); fd.append("migrationZip", file);
      const res = await fetch(`${BACKEND_URL}/api/process-migration`, { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok || !data.success) throw new Error(data.error || "Processing failed");
      setResults(data); setStatus(STATUS.DONE);
      setHistory(h => [{
        id: Date.now(), date: new Date().toLocaleString(), file: file.name,
        users: data.affectedUsers, sent: data.successCount, failed: data.failedCount
      }, ...h]);
    } catch (err) { setErrorMsg(err.message); setStatus(STATUS.ERROR); }
  }

  function reset() { setFile(null); setStatus(STATUS.IDLE); setPreview(null); setResults(null); setErrorMsg(""); setProgress(0); }
  const isLoading = status === STATUS.PREVIEWING || status === STATUS.PROCESSING;

  const navItems = [
    { id: "dashboard", icon: "M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6", label: "Dashboard" },
    { id: "process",   icon: "M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z", label: "Process ZIP" },
    { id: "history",   icon: "M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2", label: "History" },
    { id: "settings",  icon: "M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z M15 12a3 3 0 11-6 0 3 3 0 016 0z", label: "Settings" },
  ];

  return (
    <div style={s.root}>
      <style>{css}</style>

      {/* Sidebar */}
      <aside style={s.sidebar}>
        <div style={s.sidebarTop}>
          <div style={s.logo}>
            <div style={s.logoIcon}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>
              </svg>
            </div>
            <div>
              <div style={s.logoName}>MigraPulse</div>
              <div style={s.logoSub}>CHSPSC LLC</div>
            </div>
          </div>
          <nav style={s.nav}>
            {navItems.map(item => (
              <div key={item.id} style={{ ...s.navItem, ...(page === item.id ? s.navItemActive : {}) }}
                onClick={() => { setPage(item.id); if(item.id==="process") reset(); }} className="nav-item">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d={item.icon}/></svg>
                <span>{item.label}</span>
              </div>
            ))}
          </nav>
        </div>
        <div style={s.sidebarBottom}>
          <div style={s.sidebarUser}>
            <div style={s.avatar}>IT</div>
            <div>
              <div style={{ fontSize:13, fontWeight:600, color:"#f1f5f9" }}>IT Admin</div>
              <div style={{ fontSize:11, color:"#94a3b8" }}>Migration Team</div>
            </div>
          </div>
        </div>
      </aside>

      {/* Main */}
      <main style={s.main}>

        {/* Dashboard page */}
        {page === "dashboard" && (
          <>
            <header style={s.topbar}>
              <div>
                <h1 style={s.pageTitle}>Dashboard</h1>
                <p style={s.pageSubtitle}>Automated User Migration Reporting Notification Tool</p>
              </div>
              <div style={s.statusBadge}><span style={s.statusDot}></span>Power Automate connected</div>
            </header>

            <div style={s.dashGrid}>
              <div style={s.dashCard} onClick={() => setPage("process")} className="dash-card">
                <div style={{ ...s.dashIcon, background:"linear-gradient(135deg,#0ea5e9,#0284c7)" }}>
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg>
                </div>
                <h3 style={s.dashCardTitle}>Process ZIP</h3>
                <p style={s.dashCardDesc}>Upload a migration report ZIP and send automated error emails to affected users with Excel reports attached.</p>
                <div style={s.dashCardLink}>Get started →</div>
              </div>

              <div style={s.dashCard} onClick={() => setPage("history")} className="dash-card">
                <div style={{ ...s.dashIcon, background:"linear-gradient(135deg,#8b5cf6,#6d28d9)" }}>
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
                </div>
                <h3 style={s.dashCardTitle}>History</h3>
                <p style={s.dashCardDesc}>View all previously processed migration reports and email delivery status for each run.</p>
                <div style={s.dashCardLink}>View history →</div>
              </div>

              <div style={s.dashCard} onClick={() => setPage("settings")} className="dash-card">
                <div style={{ ...s.dashIcon, background:"linear-gradient(135deg,#f59e0b,#d97706)" }}>
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                </div>
                <h3 style={s.dashCardTitle}>Settings</h3>
                <p style={s.dashCardDesc}>Configure Power Automate URL, IT admin email, email templates, and notification preferences.</p>
                <div style={s.dashCardLink}>Configure →</div>
              </div>
            </div>

            <div style={s.infoBox}>
              <div style={s.infoBoxIcon}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#0ea5e9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
              </div>
              <div>
                <div style={{ fontSize:14, fontWeight:600, color:"#0f172a", marginBottom:4 }}>How it works</div>
                <div style={{ fontSize:13, color:"#64748b", lineHeight:1.6 }}>
                  1. Export migration ZIP from <strong>Microsoft 365 Admin Center → Migration and imports</strong><br/>
                  2. Upload ZIP here → Preview errors by user → Send emails<br/>
                  3. Each affected user receives a professional email with a colored Excel error report attached<br/>
                  4. Power Automate handles delivery via Outlook — zero manual work
                </div>
              </div>
            </div>
          </>
        )}

        {/* Process ZIP page */}
        {(page === "process" || page === "dashboard_process") && page === "process" && (
          <>
            <header style={s.topbar}>
              <div>
                <h1 style={s.pageTitle}>Process migration ZIP</h1>
                <p style={s.pageSubtitle}>Upload → Preview → Send automated error emails</p>
              </div>
              <div style={s.statusBadge}><span style={s.statusDot}></span>Power Automate connected</div>
            </header>

            {!results && (
              <div style={s.stepTracker}>
                {[
                  { n:1, label:"Upload ZIP",     done: !!file },
                  { n:2, label:"Preview errors", done: !!preview },
                  { n:3, label:"Send emails",    done: status === STATUS.DONE },
                ].map((step,i) => (
                  <div key={i} style={s.stepItem}>
                    <div style={{ ...s.stepCircle, ...(step.done ? s.stepDone : (i===0&&!file)||(i===1&&file&&!preview)||(i===2&&preview) ? s.stepActive : {}) }}>
                      {step.done ? <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg> : step.n}
                    </div>
                    <span style={s.stepLabel}>{step.label}</span>
                    {i < 2 && <div style={s.stepLine}/>}
                  </div>
                ))}
              </div>
            )}

            <div style={s.contentGrid}>
              {!results && (
                <div style={s.card}>
                  <div style={s.cardHeader}>
                    <div style={s.cardIcon}>
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg>
                    </div>
                    <div>
                      <h2 style={s.cardTitle}>Upload migration report</h2>
                      <p style={s.cardSub}>Drop the ZIP file exported from Microsoft 365 Admin Center</p>
                    </div>
                  </div>

                  <div style={{ ...s.dropzone, ...(dragOver?s.dropzoneHover:{}), ...(file?s.dropzoneFilled:{}) }}
                    onClick={() => !file && inputRef.current.click()}
                    onDragOver={e => { e.preventDefault(); setDragOver(true); }}
                    onDragLeave={() => setDragOver(false)}
                    onDrop={handleDrop} className="dropzone">
                    <input ref={inputRef} type="file" accept=".zip" style={{ display:"none" }} onChange={e => handleFile(e.target.files[0])}/>
                    {file ? (
                      <div style={s.fileRow}>
                        <div style={s.fileIconBox}>
                          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#0ea5e9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M13 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V9z"/><polyline points="13 2 13 9 20 9"/></svg>
                        </div>
                        <div style={{ flex:1 }}>
                          <div style={{ fontSize:14, fontWeight:600, color:"#0f172a" }}>{file.name}</div>
                          <div style={{ fontSize:12, color:"#64748b", marginTop:2 }}>{(file.size/1024).toFixed(1)} KB · Ready to process</div>
                        </div>
                        <button style={s.removeBtn} onClick={e => { e.stopPropagation(); reset(); }}>
                          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                        </button>
                      </div>
                    ) : (
                      <div style={{ textAlign:"center" }}>
                        <div style={s.uploadIconWrap}>
                          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#0ea5e9" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg>
                        </div>
                        <p style={{ margin:"0 0 6px", fontSize:15, fontWeight:600, color:"#0f172a" }}>Drop your migration ZIP here</p>
                        <p style={{ margin:0, fontSize:13, color:"#64748b" }}>or <span style={{ color:"#0ea5e9", cursor:"pointer" }}>click to browse</span> · accepts Migration_summary_report.zip</p>
                      </div>
                    )}
                  </div>

                  {errorMsg && (
                    <div style={s.errorBox}>
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                      {errorMsg}
                    </div>
                  )}

                  {file && (
                    <div style={s.btnRow}>
                      <button style={{ ...s.btn, ...s.btnGhost }} onClick={handlePreview} disabled={isLoading} className="btn">
                        {status===STATUS.PREVIEWING ? <Spinner/> : <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>}
                        {status===STATUS.PREVIEWING ? "Parsing…" : "Preview errors"}
                      </button>
                      <button style={{ ...s.btn, ...s.btnPrimary, ...(!preview?s.btnDisabled:{}) }} onClick={handleProcess} disabled={!preview||isLoading} className="btn">
                        {status===STATUS.PROCESSING ? <Spinner white/> : <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>}
                        {status===STATUS.PROCESSING ? "Sending emails…" : "Send all emails"}
                      </button>
                    </div>
                  )}

                  {status===STATUS.PROCESSING && (
                    <div style={s.progressWrap}>
                      <div style={s.progressBar}><div style={{ ...s.progressFill, width:`${progress}%` }}/></div>
                      <span style={s.progressLabel}>{progress}%</span>
                    </div>
                  )}
                </div>
              )}

              {preview && !results && (
                <div style={s.card} className="fade-in">
                  <div style={s.cardHeader}>
                    <div style={{ ...s.cardIcon, background:"linear-gradient(135deg,#8b5cf6,#6d28d9)" }}>
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
                    </div>
                    <div>
                      <h2 style={s.cardTitle}>Error preview — {preview.affectedUsers} user(s) found</h2>
                      <p style={s.cardSub}>{preview.totalErrors} total errors · {preview.sourceFile}</p>
                    </div>
                  </div>
                  <div style={s.statRow}>
                    <StatCard label="Users affected" value={preview.affectedUsers} color="#6d28d9" bg="#f5f3ff"/>
                    <StatCard label="Total errors"   value={preview.totalErrors}   color="#dc2626" bg="#fef2f2"/>
                    <StatCard label="Emails to send" value={preview.affectedUsers} color="#059669" bg="#f0fdf4"/>
                  </div>
                  <div style={s.tableWrap}>
                    <table style={s.table}>
                      <thead><tr>{["User email","Errors","Error codes","Files (sample)"].map(h=><th key={h} style={s.th}>{h}</th>)}</tr></thead>
                      <tbody>
                        {preview.users.map((u,i)=>(
                          <tr key={i} style={{ background:i%2===0?"#fff":"#f8fafc" }}>
                            <td style={s.td}><div style={{ display:"flex",alignItems:"center",gap:8 }}><div style={s.emailAvatar}>{u.userEmail[0].toUpperCase()}</div><span style={{ fontSize:13,color:"#0f172a" }}>{u.userEmail}</span></div></td>
                            <td style={{ ...s.td,textAlign:"center" }}><span style={s.errorBadge}>{u.errorCount}</span></td>
                            <td style={s.td}>{u.errorCodes.map(c=><span key={c} style={s.codePill}>{c.replace("MEXPORTFILEUNSUPPORTEDMIMETYPE","SHORTCUT").replace("MVERSIONDOWNLOAD","VERSION_DL")}</span>)}</td>
                            <td style={{ ...s.td,fontSize:12,color:"#64748b" }}>{u.preview.map(p=>p.file).join(", ")}{u.errorCount>3?` +${u.errorCount-3} more`:""}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div style={s.previewNote}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#0ea5e9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>
                    Each user will receive a professional email with a fully colored Excel report attached.
                  </div>
                </div>
              )}

              {results && (
                <div style={s.card} className="fade-in">
                  <div style={s.resultHeader}>
                    <div style={s.resultCheck}>
                      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                    </div>
                    <div>
                      <h2 style={{ margin:0,fontSize:20,fontWeight:700,color:"#0f172a" }}>All done!</h2>
                      <p style={{ margin:"2px 0 0",fontSize:13,color:"#64748b" }}>{results.successCount} email(s) sent · {results.failedCount} failed · {results.sourceFile}</p>
                    </div>
                  </div>
                  <div style={s.statRow}>
                    <StatCard label="Emails sent"    value={results.successCount}  color="#059669" bg="#f0fdf4"/>
                    <StatCard label="Failed"         value={results.failedCount}   color={results.failedCount>0?"#dc2626":"#64748b"} bg={results.failedCount>0?"#fef2f2":"#f8fafc"}/>
                    <StatCard label="Users notified" value={results.affectedUsers} color="#0ea5e9" bg="#f0f9ff"/>
                  </div>
                  <div style={s.tableWrap}>
                    <table style={s.table}>
                      <thead><tr>{["User email","Errors","Excel report","Status"].map(h=><th key={h} style={s.th}>{h}</th>)}</tr></thead>
                      <tbody>
                        {results.results.map((r,i)=>(
                          <tr key={i} style={{ background:i%2===0?"#fff":"#f8fafc" }}>
                            <td style={s.td}><div style={{ display:"flex",alignItems:"center",gap:8 }}><div style={s.emailAvatar}>{r.userEmail[0].toUpperCase()}</div><span style={{ fontSize:13,color:"#0f172a" }}>{r.userEmail}</span></div></td>
                            <td style={{ ...s.td,textAlign:"center" }}><span style={s.errorBadge}>{r.errorCount}</span></td>
                            <td style={{ ...s.td,fontSize:12,color:"#64748b" }}>{r.csvFileName}</td>
                            <td style={s.td}><span style={{ ...s.statusPill,...(r.status==="triggered"?s.statusSent:s.statusFailed) }}>{r.status==="triggered"?"✓ Sent":"✗ Failed"}</span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div style={s.btnRow}>
                    <button style={{ ...s.btn,...s.btnGhost }} onClick={reset} className="btn">
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 11-2.12-9.36L23 10"/></svg>
                      Process another ZIP
                    </button>
                  </div>
                </div>
              )}
            </div>
          </>
        )}

        {/* History page */}
        {page === "history" && (
          <>
            <header style={s.topbar}>
              <div>
                <h1 style={s.pageTitle}>History</h1>
                <p style={s.pageSubtitle}>All previously processed migration reports this session</p>
              </div>
            </header>
            <div style={s.card}>
              <div style={s.cardHeader}>
                <div style={{ ...s.cardIcon, background:"linear-gradient(135deg,#8b5cf6,#6d28d9)" }}>
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
                </div>
                <div>
                  <h2 style={s.cardTitle}>Migration runs</h2>
                  <p style={s.cardSub}>{history.length} run(s) this session</p>
                </div>
              </div>
              {history.length === 0 ? (
                <div style={{ padding:"48px 24px", textAlign:"center" }}>
                  <div style={{ fontSize:40, marginBottom:12 }}>📭</div>
                  <p style={{ fontSize:15, fontWeight:600, color:"#0f172a", marginBottom:6 }}>No runs yet</p>
                  <p style={{ fontSize:13, color:"#64748b", marginBottom:20 }}>Process a migration ZIP to see the history here.</p>
                  <button style={{ ...s.btn,...s.btnPrimary, margin:"0 auto" }} onClick={() => { setPage("process"); reset(); }} className="btn">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg>
                    Process a ZIP
                  </button>
                </div>
              ) : (
                <div style={s.tableWrap}>
                  <table style={s.table}>
                    <thead><tr>{["Date","Source file","Users","Sent","Failed","Status"].map(h=><th key={h} style={s.th}>{h}</th>)}</tr></thead>
                    <tbody>
                      {history.map((h,i)=>(
                        <tr key={h.id} style={{ background:i%2===0?"#fff":"#f8fafc" }}>
                          <td style={{ ...s.td,fontSize:12,color:"#64748b" }}>{h.date}</td>
                          <td style={{ ...s.td,fontSize:13,color:"#0f172a",fontWeight:500 }}>{h.file}</td>
                          <td style={{ ...s.td,textAlign:"center" }}>{h.users}</td>
                          <td style={{ ...s.td,textAlign:"center" }}><span style={{ color:"#059669",fontWeight:600 }}>{h.sent}</span></td>
                          <td style={{ ...s.td,textAlign:"center" }}><span style={{ color:h.failed>0?"#dc2626":"#64748b",fontWeight:600 }}>{h.failed}</span></td>
                          <td style={s.td}><span style={{ ...s.statusPill,...(h.failed===0?s.statusSent:{background:"#fef3c7",color:"#92400e"}) }}>{h.failed===0?"✓ Complete":"⚠ Partial"}</span></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </>
        )}

        {/* Settings page */}
        {page === "settings" && (
          <>
            <header style={s.topbar}>
              <div>
                <h1 style={s.pageTitle}>Settings</h1>
                <p style={s.pageSubtitle}>Configure your migration notification tool</p>
              </div>
